CREATE TABLE IF NOT EXISTS academic_drafts (user_id VARCHAR(32) NOT NULL,course_id VARCHAR(20) NOT NULL,module_index INTEGER NOT NULL,task_kind VARCHAR(12) NOT NULL,document_json MEDIUMTEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at VARCHAR(30) NOT NULL,PRIMARY KEY(user_id,course_id,module_index,task_kind),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS academic_submissions (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,course_id VARCHAR(20) NOT NULL,module_index INTEGER NOT NULL,task_kind VARCHAR(12) NOT NULL,revision INTEGER NOT NULL,document_json MEDIUMTEXT NOT NULL,word_count INTEGER NOT NULL,status VARCHAR(24) NOT NULL,feedback TEXT NULL,rubric_json TEXT NULL,reviewed_by VARCHAR(32) NULL,reviewed_at VARCHAR(30) NULL,submitted_at VARCHAR(30) NOT NULL,UNIQUE(user_id,course_id,module_index,task_kind,revision),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS academic_college_passes (user_id VARCHAR(32) NOT NULL,module_index INTEGER NOT NULL,passed_at VARCHAR(30) NOT NULL,PRIMARY KEY(user_id,module_index),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS academic_integrity_acceptance (user_id VARCHAR(32) PRIMARY KEY,policy_version INTEGER NOT NULL,accepted_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
